CREATE VIEW cdn.[CrmTerminarzOperatorzyView_SRV1](Typ, Id, KodOpiekuna, Caption) AS SELECT  DISTINCT CrU_PodmiotTyp, CrU_PodmiotId, CASE CrU_PodmiotTyp WHEN 8 THEN CASE CrU_PodmiotId WHEN 0 THEN '' WHEN 1 THEN 'ADMIN' WHEN 12 THEN 'BARTEK' WHEN 3 THEN 'DAREK' WHEN 10 THEN 'GOSIA' WHEN 14 THEN 'JAREK' WHEN 5 THEN 'KRZYSZTOF' WHEN 4 THEN 'LESZEK' WHEN 8 THEN 'LIDIA' WHEN 6 THEN 'MACIEJ' WHEN 9 THEN 'MAGDA' WHEN 11 THEN 'MAGDALENA' WHEN 7 THEN 'MAŁGORZATA' WHEN 13 THEN 'ONE_DOD' END ELSE IsNull((SELECT TOP 1 PRI_Kod FROM cdn.PracIdx WHERE PRI_PraID=CrU_PodmiotId), '') END,CASE CrU_PodmiotTyp WHEN 8 THEN CASE CrU_PodmiotId WHEN 0 THEN '' WHEN 1 THEN 'Administrator' WHEN 12 THEN 'Bartosz Jędrzejewski' WHEN 3 THEN 'Dariusz Wandel' WHEN 14 THEN 'Jarosław Ziemborski' WHEN 5 THEN 'Krzysztof Groszak' WHEN 4 THEN 'Leszek Pawełczak' WHEN 8 THEN 'Lidia Jodłowska' WHEN 6 THEN 'Maciej Pawełczak' WHEN 11 THEN 'Magdalena Łubińska' WHEN 9 THEN 'Magdalena Oleśkowicz-Popiel' WHEN 10 THEN 'Małgorzata Baranowska' WHEN 7 THEN 'Małgorzata Hemmerling' WHEN 13 THEN 'One Dodatki' END ELSE IsNull((SELECT TOP 1 PRI_Imie1 + SPACE(1) + PRI_Nazwisko As Nazwisko FROM cdn.PracIdx WHERE PRI_PraID=CrU_PodmiotId), '') END FROM CDN.CRMKontakty JOIN CDN.CrmUczestnicy ON CrU_CrKId = CrK_CrKId JOIN CDN.PodmiotyView ON Pod_PodId = CrK_PodId AND Pod_PodmiotTyp = CrK_PodmiotTyp WHERE CRK_Zadanie = 1 And CRK_Bufor > -1 UNION SELECT DISTINCT SrY_SerwisantTyp, SrY_SerwisantID, CASE SrY_SerwisantTyp WHEN 8 THEN CASE SrY_SerwisantID WHEN 0 THEN '' WHEN 1 THEN 'ADMIN' WHEN 12 THEN 'BARTEK' WHEN 3 THEN 'DAREK' WHEN 10 THEN 'GOSIA' WHEN 14 THEN 'JAREK' WHEN 5 THEN 'KRZYSZTOF' WHEN 4 THEN 'LESZEK' WHEN 8 THEN 'LIDIA' WHEN 6 THEN 'MACIEJ' WHEN 9 THEN 'MAGDA' WHEN 11 THEN 'MAGDALENA' WHEN 7 THEN 'MAŁGORZATA' WHEN 13 THEN 'ONE_DOD' END ELSE IsNull((SELECT TOP 1 PRI_Kod FROM cdn.PracIdx WHERE PRI_PraID=SrY_SerwisantID), '') END,CASE SrY_SerwisantTyp WHEN 8 THEN CASE SrY_SerwisantID WHEN 0 THEN '' WHEN 1 THEN 'Administrator' WHEN 12 THEN 'Bartosz Jędrzejewski' WHEN 3 THEN 'Dariusz Wandel' WHEN 14 THEN 'Jarosław Ziemborski' WHEN 5 THEN 'Krzysztof Groszak' WHEN 4 THEN 'Leszek Pawełczak' WHEN 8 THEN 'Lidia Jodłowska' WHEN 6 THEN 'Maciej Pawełczak' WHEN 11 THEN 'Magdalena Łubińska' WHEN 9 THEN 'Magdalena Oleśkowicz-Popiel' WHEN 10 THEN 'Małgorzata Baranowska' WHEN 7 THEN 'Małgorzata Hemmerling' WHEN 13 THEN 'One Dodatki' END ELSE IsNull((SELECT TOP 1 PRI_Imie1 + SPACE(1) + PRI_Nazwisko As Nazwisko FROM cdn.PracIdx WHERE PRI_PraID=SrY_SerwisantID), '') END FROM CDN.SrsCzynnosci JOIN cdn.SrsZlecenia on SrY_SrZId = SrZ_SrZId JOIN CDN.PodmiotyView ON Pod_PodId = SrZ_PodmiotId AND Pod_PodmiotTyp = SrZ_PodmiotTyp WHERE SrZ_Bufor > -1 AND SrY_Realizacja = 2 AND SrY_RezerwujCzas = 1 UNION SELECT DISTINCT 8, DnE_OpeID, CASE DnE_OpeID WHEN 0 THEN '' WHEN 1 THEN 'ADMIN' WHEN 12 THEN 'BARTEK' WHEN 3 THEN 'DAREK' WHEN 10 THEN 'GOSIA' WHEN 14 THEN 'JAREK' WHEN 5 THEN 'KRZYSZTOF' WHEN 4 THEN 'LESZEK' WHEN 8 THEN 'LIDIA' WHEN 6 THEN 'MACIEJ' WHEN 9 THEN 'MAGDA' WHEN 11 THEN 'MAGDALENA' WHEN 7 THEN 'MAŁGORZATA' WHEN 13 THEN 'ONE_DOD' END,CASE DnE_OpeID WHEN 0 THEN '' WHEN 1 THEN 'Administrator' WHEN 12 THEN 'Bartosz Jędrzejewski' WHEN 3 THEN 'Dariusz Wandel' WHEN 14 THEN 'Jarosław Ziemborski' WHEN 5 THEN 'Krzysztof Groszak' WHEN 4 THEN 'Leszek Pawełczak' WHEN 8 THEN 'Lidia Jodłowska' WHEN 6 THEN 'Maciej Pawełczak' WHEN 11 THEN 'Magdalena Łubińska' WHEN 9 THEN 'Magdalena Oleśkowicz-Popiel' WHEN 10 THEN 'Małgorzata Baranowska' WHEN 7 THEN 'Małgorzata Hemmerling' WHEN 13 THEN 'One Dodatki' END FROM CDN.DokNagProcesEtapyView JOIN cdn.DokNagEtapyView on DnE_Typ = DnPr_Typ and DnE_DnPrID = DnPr_DnPrId JOIN cdn.DokNagView  on DnPr_Typ = DnV_Typ and DnPr_DoNId = DnV_DoNId WHERE DnE_RezerwujCzas = 1